/** INC-28 U1: the module the may-throw analysis reads. On this tier the
 * three spawnSync keys THROW (Node's own argument validation —
 * ERR_INVALID_ARG_VALUE, ERR_OUT_OF_RANGE, ERR_UNKNOWN_SIGNAL — before the
 * child runs), where the native lanes never do (board #209 owns their
 * cells), so the shared may-throw list (ir/nodes.ts MAY_THROW_LIB_FNS)
 * deliberately does not carry them. Without a pending check after every
 * call that can reach one, a caller would never see the throw. So when the
 * module contains one of the three, the analysis runs over a COPY in which
 * exactly those libCall names read as cp.execSync (already on the list);
 * the copy is used for nothing else and never emitted. A module with none
 * of them gets the ORIGINAL object back — its analysis, and its bytes, are
 * exactly what they were. INC-28 U2 adds the asynchronous keys that throw
 * here and not on the native lanes: spawn and spawn with options (the same
 * argument validation, and the synchronously thrown spawn failures), and
 * kill with a number (Node's ERR_UNKNOWN_SIGNAL for a number naming no
 * signal; child.kill with a name is already on the shared list). */
function spawnSyncMayThrowView(mod: WModule): WModule {
  // INC-29 U1: node:net's synchronous throws on this tier — listen's
  // ERR_SERVER_ALREADY_LISTEN and port check, connect's host and port
  // checks, and server.address().port before a listen (null.port).
  // Board #233: parseGetTime's S069 fence throws on this tier only (the
  // native lanes answer a value), so a caller must check after the call;
  // without it the fence was swallowed inside a function and an uncaught
  // one at top level exited 0 with no output.
  // Board #235: encodeURI / encodeURIComponent throw URIError on a lone
  // surrogate on this tier (UTF-16 strings); the native lanes' UTF-8
  // strings cannot hold one, so the shared list says they never throw.
  const keys = new Set([
    "date.parseGetTime",
    "str.encodeUri",
    "str.encodeUriComponent",
    "cp.spawnSync", "cp.spawnSyncOpts", "cp.spawnSyncStdioStr", "cp.spawn", "cp.spawnOpts", "child.killNum",
    "net.listen", "net.listenCb", "net.listenOpts", "net.listenOptsCb", "net.connect", "net.connectCb", "net.serverPort",
    // node:querystring: escape and stringify throw URIError
    // [ERR_INVALID_URI] for a string ending in a surrogate (encodeStr);
    // the native lanes never throw there (board #232).
    "qs.escape", "qs.stringify",
    // Unit H: Atomics.wait's index check throws Node's RangeError on this
    // tier; the native lanes trap on an out-of-range index instead.
    "atomics.wait",
    // Unit G2: an interface's 'close' listeners run inside close(), and a
    // throw from one reaches close()'s caller.
    "rl.close",
  ]);
  let found = false;
  const scan = (node: unknown): void => {
    if (found) return;
    if (Array.isArray(node)) {
      for (const item of node) scan(item);
      return;
    }
    if (node !== null && typeof node === "object") {
      const rec = node as Record<string, unknown>;
      if (rec["kind"] === "libCall" && typeof rec["fn"] === "string" && keys.has(rec["fn"])) {
        found = true;
        return;
      }
      for (const value of Object.values(rec)) scan(value);
    }
  };
  scan(mod.functions);
  // INC-29 U4: the socketless TLS keys (createSecureContext, the CA store) throw too.
  const netKeys = netModuleReachable(mod) || libCallWhere(mod, isTlsKey);
  if (!found && !netKeys) return mod;
  const copy = (node: unknown): unknown => {
    if (Array.isArray(node)) return node.map(copy);
    if (node !== null && typeof node === "object") {
      const out: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(node as Record<string, unknown>)) out[k] = copy(v);
      if (out["kind"] === "libCall" && typeof out["fn"] === "string" && keys.has(out["fn"])) out["fn"] = "cp.execSync";
      // INC-29 U2: every node:http key can throw here (Node's validation
      // ladders, the named fences), so each reads as a throwing call.
      if (out["kind"] === "libCall" && typeof out["fn"] === "string" && out["fn"].startsWith("http.")) out["fn"] = "cp.execSync";
      // INC-29 U4: every node:tls / node:https / CA-store / node:dgram key
      // can throw here (Node's ladders, the host's material errors, the
      // named fences).
      if (out["kind"] === "libCall" && typeof out["fn"] === "string" && (isTlsKey(out["fn"]) || out["fn"].startsWith("dgram."))) out["fn"] = "cp.execSync";
      // INC-29 U1 (review): in a module that boxes net handles, `in` on a
      // checked-dynamic value can throw (the handle fence), so it reads as
      // a throwing call here.
      if (out["kind"] === "dynHasKey" && netKeys) {
        return { kind: "libCall", fn: "cp.execSync", args: [out["value"]], type: out["type"], loc: out["loc"] };
      }
      return out;
    }
    return node;
  };
  return { ...mod, functions: copy(mod.functions) as WModule["functions"] };
}

