      c.call(dyn.objGet());
      c.localTee(M);
      c.refIsNull();
      c.i32Eqz();
      c.ifVoid();
      c.localGet(M);
      c.structGet(dynT, DYN_KIND);
      c.i32Const(DK.FUNC);
      c.i32Eq();
      c.ifVoid();
      c.localGet(D);
      c.call(dyn.thisPush());
      c.localGet(M);
      c.i32Const(0);
      c.i32Const(0);
      c.arrayNewDefault(vec.bufType);
      c.structNew(vec.struct);
      this.pushStrLitInto(c, name);
      c.call(dyn.callFn());
      c.localSet(R);
      c.call(dyn.thisPop());
      c.localGet(R);
      c.refIsNull();
      c.ifVoid();
      c.refNull(this.strType);
      c.return_();
      c.end();
      isPrim(R);
      c.ifVoid();
      c.localGet(R);
      c.call(dyn.toStr());
