                  code.localGet(subjLocal);
                  code.localGet(qLocal);
                  code.i32Const(flags.unicode ? 1 : 0);
                  code.call(this.regexInterp.getChar());
                  code.localSet(qLocal); // newIdx (getChar's own result order — see its doc comment)
